interface UserProfile {
  id: string;
  name: string;
  email: string;
  avatarUrl?: string;
  bio?: string;
}

/**
 * Fetches user profile data from an external API
 * @param userId - The unique identifier for the user
 * @returns A Promise that resolves to the UserProfile object
 * @throws Will throw an error if the request fails due to network issues, timeout, or server errors (500+)
 */
async function fetchUserProfile(userId: string): Promise<UserProfile> {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000); // 5-second timeout

    const response = await fetch(`https://api.example.com/users/${userId}`, {
      signal: controller.signal,
      headers: {
        'Accept': 'application/json',
      }
    });

    clearTimeout(timeoutId);

    // Handle HTTP errors (4xx and 5xx status codes)
    if (!response.ok) {
      if (response.status >= 500) {
        throw new Error(`Server error (${response.status}): ${response.statusText}`);
      }
      if (response.status >= 400 && response.status < 500) {
        throw new Error(`Client error (${response.status}): ${response.statusText}`);
      }
      throw new Error(`Unexpected HTTP status: ${response.status}`);
    }

    const data: UserProfile = await response.json();
    return data;

  } catch (error) {
    // Handle specific error types
    if (error instanceof Error) {
      if (error.name === 'AbortError') {
        throw new Error(`Request timed out for user ID: ${userId}`);
      }
      // Re-throw with more context for network errors
      if (error.message.includes('fetch')) {
        throw new Error(`Network error while fetching user profile for ID: ${userId}`);
      }
    }

    // Re-throw the error with additional context
    throw new Error(`Failed to fetch user profile for ID ${userId}: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}
